		org	$bf000;----------------------------------------------------------------------;;	Pocket Link Cache Device Driver ver 1.62;	Installation program;	for PC-E500 series pocket computer;	Copyright (c) 1996,1997,1999 by Daisuke Mizobata;;	based on PLINK.SYS ver 1.04;	Copyright (c) 1990,93,94 N.Kon;;----------------------------------------------------------------------;;----------------------------------------------------------------------;		Differentes definitions numeriques;----------------------------------------------------------------------fcs:			equ	$fffe4iocs:			equ	$fffe8iocs_fook:		equ	$bfca2sio_rcv_vct:	equ	$bfcd5sio_param:		equ	$bfd33base:			equ	$ecbx:				equ	$d4cx:				equ	$d6cl:				equ	$d6ch:				equ	$d7dx:				equ	$d8key_strobe_2:	equ	$f1sio_ctrl_reg:	equ	$f7sio_stat_reg:	equ	$f8sio_rx_reg:		equ	$f9sio_tx_reg:		equ	$faintr_mask_reg:	equ	$fbsystem_stat_reg:equ	$ffbtext:	equ	$cbbdata:	equ	$cebpmax:	equ	$caiwork:	equ	$e6keyvec:	equ	$bfc41s1top:	equ	$bfc15s1end:	equ	$bfcdecdrv:	equ	$bfc7drev:	equ	$bfca1iroot:	equ	$bfca2bworkp:	equ	$bfd0esectsiz:	equ	128cache_sect:	equ	sectsiz+1cache_next:	equ	cache_sect+2cache_size:	equ	cache_next+3n_fcache:	equ	7		;	Nombre de secteurs dans le cache FATn_dcache:	equ	1		;	Nombre de secteurs dans le cache de donneesdtop:		equ	44timeout:	equ	40000		; Delai d'attente (environ 1 seconde)#DEFMACRO bsr	rel call	%0#ENDMACRO;;	Installateur;pntr	dest,bottom,mdf,offsetentry:	pre	$32	sub	($ec),%	mv	il,title-mb	call	putm2;	"L:" existe-t-il deja?	mv	x,dvname	mv	il,0	call	icall			;	Recherche de nom de lecteur	mv	il,exi_m-mb	jpnc	msend;	Si un bloc de memoire existe	mv	x,btop+1	mv	il,$41	call	memd	mv	il,exi_m-mb	jpnc	msend	mv	y,[iroot]			;	Debut de la liste d'en-tete IOCS d'origine	mv	[ihead],y;	Definir le numero de peripherique	pre	$32	mv	(cx),10-1			;	Numero de peripherique planifie 10	{		pre	$32		inc	(cx)		mv	il,1		call	icall		jrnc	continue	}	pre	$32	mv	[devno],(cx)		;	Definir le numero de peripherique	mv	il,$47	call	memd;	Verifiez l'emplacement d'installation	mv	x,[s1top]	mv	y,[x+$12]loop1:	add	x,y	mv	(dest),x	mv	a,[x]	cmp	a,$fb	jrnz	chksize	mv	a,[x+$0c]	test	a,$0cloop2:	mv	y,[x+$11]	jrnz	loop1	add	x,y	mv	a,[x]	cmp	a,$fb	jrz	loop2chksize:;	 Verifiez si le programme depasse la limite de 64 Ko	mv	i,prgend-btop		;	Taille du conducteur seulement	mv	ba,(dest)	add	ba,i	mv	il,pg_m-mb	jrc	msend2;	Verifier la capacite de la memoire	mv	(bottom),x	mv	y,[s1end]	sub	y,x	dec	y	mv	ba,blen	sub	y,ba	mv	il,mem_m-mb	jrc	msend2;	Bloc memoire Stagger	mv	x,(bottom)	mv	y,(dest)	sub	x,y	inc	x				;	x = nombre d'octets a deplacer	pushu	imr			;	Desactiver l'interruption	mv	[--s],u			;	pushs	u	mv	y,(bottom)	mv	u,(bottom)	add	u,ba	inc	u	inc	y	{		mv	a,[--y]		pushu	a		;	mv	[--u],a		dec	x	jrnz	continue	};	Chauffeur de transfert	mv	u,btop	mv	x,(dest)	mv	[--s],u			;	pushs	u	sub	u,x	mv	(offset),u	mv	u,[s++]			;	pops	u	mv	i,prgend-btop	;	Taille du conducteur seulement	{		popu	a		;	mv	a,[u++]		mv	[x++],a		dec	i		jrnz	continue	};	Relocaliser le traitement	mv	y,(dest)	mv	ba,btop-entry	sub	y,ba	{		popu	a		;	mv	a,[u++]		cmp	a,$ff		jrz	break		mv	il,2		test	a,$80		jrz	word		inc	ilword:		and	a,$7f		cmp	a,$7e		jrnz	short		popu	ba		;	mv	ba,[u++]		add	y,ba		db	$0a			;	Passer les 2 octets suivantsshort:		add	y,a				mvp	(mdf),[y]		sbcl	(mdf),(offset)		mvp	[y],(mdf)		jr	continue	}	mv	u,[s++]			;	pops	u;	S'inscrire a la liste IOCS	mv	x,(dest)	mv	a,ihead-btop	add	x,a	mv	[iroot],x	popu	imr	mv	x,dvname	mv	il,$04	call	icall		;	Initialisation des parametres	mv	il,ins_m-mbmsend2:	pushu	i	call	linkbas		;	Corrigez les pointeurs de BTEXT $ et BDATA $ en BASIC	mv	a,0	pre	$32	mv	[(iwork)+$3a],a	;	Detachez RAMFILE	popu	imsend:	call	putm2	pre	$32	add	($ec),%	retfputm2:	mv	x,mb	add	x,i	mv	il,[x++]	mv	y,i	pre	$32	mv	(cx),0	mv	il,$04	callf	fcs	retlinkbas:;	Pointeur de BTEXT $ et BDATA $	pre	$32	mv	x,[bworkp]	mv	a,$72	add	x,a	call	bsearch	jrc	bomb	pre	$32	mv	(btext),y	call	bsearch	jrc	bomb	pre	$32	mv	(bdata),y	retbomb:	resetbsearch:mv	il,$41memd2:	pre	$32	mv	(cx+1),[x++]memd:	pre	$32	mv	(cx),6icall:	callf	iocs	retmb:title:	db	37+34,'PLINKC ver 1.62 by Daisuke Mizobata',$0d,$0a	db	'based on PLINK ver 1.04 by N.Kon',$0d,$0aexi_m:	db	17,'Already exists.',$0d,$0amem_m:	db	20,'Not enough memory.',$0d,$0ains_m:	db	12,'Installed.',$0d,$0apg_m:	db	17,'Over two pages.',$0d,$0a;----------------------------------------------------------------------;		En-tete du fichier d'en-tete de l'appareil;----------------------------------------------------------------------btop:	db	$fb,'PLINK   SYS'		;Nom du bloc de peripherique		db	$25						;Attributs de bloc de memoire		dw	0,0						;Date et heure		dp	blen					;Nombre d'octets dans le bloc memoire		dw	0		dp	blen					;Nombre d'octets de l'entite de fichier		dp	blen					;Nombre d'octets dans le bloc memoire		dp	0,0;----------------------------------------------------------------------;		En-tete du pilote de peripherique;----------------------------------------------------------------------ihead:		dp	0			;Adresse du prochain en-tete de pilote de peripheriquedevno:		db	0			;Numero d'appareil (variable)		db	$83				;Attribut de peripherique (identique a E :)		rel dp	devmain		;Adresse du corps du pilote de peripheriquedvname:		db	'L:',0		;Nom de l'appareil;----------------------------------------------------------------------;		Media parameter block;----------------------------------------------------------------------;Version de 128 Kompb128:		db	$f0			;Descripteur de media (peut etre approprie)		dw	sectsiz			;Nombre d'octets par secteur		db	4-1				;(Nombre d'octets par secteur / 32) -1		db	2				;log 2 (nombre d'octets par secteur / 32)		db	0				;???		db	1				;???		dw	0				;Premier numero de secteur de zone FAT		db	8				;???		dw	128				;Nombre maximum de fichiers stockables		dw	dtop			;Numero du secteur de depart de la zone de donnees		dw	980+1			;Nombre total de secteurs dans la zone de donnees + 1		db	12				;Nombre total de secteurs dans la zone FAT		dw	12				;Premier numero de secteur de la zone DIR;Donnees referencees dans DS		dw	12				;Premier numero de secteur de la zone DIR;Version de 512 Kompb512:		db	$f0		dw	sectsiz		db	4-1		db	2		db	0		db	1		dw	0		db	8		dw	128		dw	80			;Numero du secteur de depart de la zone de donnees		dw	4016+1		;Nombre total de secteurs dans la zone de donnees + 1		db	48			;Nombre total de secteurs dans la zone FAT		dw	48			;Premier numero de secteur de la zone DIR;		dw	48;----------------------------------------------------------------------;		Corps;----------------------------------------------------------------------suborg		0byte		i_work1,i_work2word		sect_num,sect_num2byte		flag,rxdata,i_work3,subkopntr		cachep,vct_rsv,beforedevmain:	pushu	imr				;Arretez l'interruption et reecrivez le vecteur de reception SIO		pushu	x		pre	$30		sub	(base),%		mv	x,[sio_rcv_vct]		mv	(vct_rsv),x			rel mv	x,rcv		mv	[sio_rcv_vct],x		popu	x		popu	imr		mv	(i_work3),[sio_param]   ;Charger les parametres		and	(i_work3),$fd	   		;Ce force a 8 bits		pre	$22		ex	(i_work3),(sio_ctrl_reg);Parametrage de la SIO & conservation du contenu precedent		pre	$22		mv	(subko),(key_strobe_2)	;Enregistrer KOH		pre	$30		or	(key_strobe_2),$60		;Activer DTR, RR;		bsr	main;		{			pre	$30			test	(sio_stat_reg),$10			jrz	continue				;Attendre la fin de la transmission		pre	$30		mv	(sio_ctrl_reg),(i_work3)	;Restaurer le parametre SIO		pre	$30		mv	(key_strobe_2),(subko)		;Restaurer KOH		test	(flag),2		jrz	jump00						;[BRK] a ete presse?		mv	a,$02		jrc	jump00brkloop:	test	[$bfcbe],$80		;Attendez que la pause soit liberee		jrnz	brkloop		mv	a,$ff						;Traitement en cas de pression		scjump00:		pushu	imr					;Restaurer le vecteur de reception SIO		pushu	x		mv	x,(vct_rsv)		mv	[sio_rcv_vct],x		pre	$30		pmdf	(base),%		popu	x		popu	imr		retf;----------------------------------------------------------------------;		Diverses commandes;----------------------------------------------------------------------init:		mv	a,[x]		cmp	a,'1'		jrnz	cmd3f_5		rel mv	x,mpb128		jr	cmd3f_15cmd3f_5:	cmp	a,'5'		jrnz	cmd3f_d		rel mv	x,mpb512cmd3f_15:	pushu	a		rel mv	[getmpb+1],x		mv	ba,[x+$c]		rel mv	[secpatch+1],ba		bsr	check_sect		mv	a,'S'		bsr	send_one		popu	a		bsr	send_one		jr	cmd3f_2cmd3f_d:	cmp	a,'D'		jrnz	cmd3f_i		bsr	check_sect				;"D" commande		mv	a,'D'		bsr	send_one				;Envoyer la commande "D"		mv	i,$12+(receive_one_s-receive_one-2)*$100		rel mv	[receive_one],i		;jr receive_one_s		jr	cmd3f_2cmd3f_i:	cmp	a,'I'		jrnz	cmd3f_2		mv	il,130					;"Je" commande		mv	a,0						;Envoyer 130 pieces de 00hcmd3f_i1:	bsr	send_one		dec	il		jrnz	cmd3f_i1cmd3f_2:	bsr	buffer_clr			;Nettoyer le tampon		;bsr	root		;retroot:		bsr	getroot			mv	[x+$a],i		mv	[x+$11],ba		rc		retgetroot:	bsr	getmpb		mv	ba,[x+$13]		mv	il,128		retgetmpb:		rel mv	x,mpb128		rc		ret;----------------------------------------------------------------------;		Corps de chaque processus;----------------------------------------------------------------------main:		mv	(flag),0		;Effacer le drapeau		mv	a,il				;Analyse de commande		cmp	a,$10		jrnz	cmd11		rc						;Traitement de commande 10h		retcmd11:		cmp	a,$11		jrz	getmpb				;Traitement de la commande 11h		cmp	a,$12		jrz	read_sect			;Traitement de commande 12h		cmp	a,$13		jrz	write_sect			;Traitement de la commande 13h		cmp	a,$14		jrz	write_sect			;Traitement de la commande 14h		cmp	a,$15		jrz	read_sect			;Traitement de commande 15h		cmp	a,$16		jrnz	cmd17		mv	ba,0				;Traitement de commande 16h		rc		retcmd17:		cmp	a,$17		jrnz	cmd18		rel mv	ba,[sect_number]	;Traitement de commande 17h		pre	$30		cmpw	(bx),ba		jrz	same_sect				;c'etait le meme secteur que le tampon		bsr	check_sect		test	(flag),2		jrnz	cmd17_err		pre	$30		mv	ba,(bx)		rel mv	[sect_number],ba		mv	(sect_num),ba		rel mv	x,sect_1		rel mv	y,sect_2		;Faire une copie		mv	il,sectsiz/2+1		bsr	rcv_sect			;Lire secteur specifie		test	(flag),2		jrz	same_sect		mv	ba,-1		rel mv	[sect_number],ba		jr	cmd17_errsame_sect:	pre	$30		mvw	(cx),sectsiz		rel mv	x,sect_1		rccmd17_err:	retcmd18:		cmp	a,$18		jrz	getroot				;Traitement de la commande $ 18 (pour DS)	cmd3f:		cmp	a,$3f		jrz	init				;Traitement de la commande 3Fhcmd40:		cmp	a,$40		jrz	root				;Traitement de commande 40hcmd_err:	mv	a,3				;Commande invalide		sc		ret;----------------------------------------------------------------------;		Lecture continue de secteurs;----------------------------------------------------------------------read_sect:	pre	$22		mvw	(sect_num),(bx)		mv	y,x		mv	il,sectsiz/2		rel mv	ba,[sect_number]		cmpw	(sect_num),ba    ;Secteurs tampons et		jrnz	read_sect1	     ;Avez-vous frappe?		rel mv	y,sect_1read_sect2:	mv	ba,[y++]		mv	[x++],ba		dec	il		jrnz	read_sect2		jr	read_sect3read_sect1:	bsr	rcv_sect		test	(flag),2		jrnz	read_errread_sect3:	pre	$30		mv	ba,(bx)		inc	ba		pre	$30		mv	(bx),ba		pre	$30		mv	ba,(dx)		dec	ba		pre	$30		mv	(dx),ba		jrnz	read_sect		rcread_err:	ret;----------------------------------------------------------------------;		Ecriture continue de secteurs;----------------------------------------------------------------------write_sect:	pre	$22		mvw	(sect_num),(bx)		mv	il,sectsiz		rel mv	ba,[sect_number]		cmpw	(sect_num),ba    ;Secteurs tampons et		jrnz	write_sect1	     ;Avez-vous frappe?		rel mv	y,sect_1write_sect2:	mv	a,[x++]		mv	[y++],a		dec	il		jrnz	write_sect2		jr	write_sect3write_sect1:	bsr	send_sect		test	(flag),2		jrnz	write_errwrite_sect3:	pre	$30		mv	ba,(bx)		inc	ba		pre	$30		mv	(bx),ba		pre	$30		mv	ba,(dx)		dec	ba		pre	$30		mv	(dx),ba		jrnz	write_sect		rcwrite_err:	ret;----------------------------------------------------------------------;		Transmission a un secteur;----------------------------------------------------------------------send_sect:	pushu	il		bsr	send_cache	;Traitement CACHE		popu	il		pushu	imr		pre	$30		mv	(intr_mask_reg),$a0		mv	y,(cachep)		pushu	ysend_sect_2:	mv	a,[x++]		mv	[y++],a		;Ecrivez a CACHE		dec	il		jrnz	send_sect_2		mv	a,'W'		bsr	send_one			;Envoyer la commande a ecrire		mv	a,(sect_num)		bsr	send_one			;Transmission inferieure a 1 octet du numero de secteur		mv	a,(sect_num+1)		bsr	send_one			;Envoi du 1 octet superieur du numero de secteur		popu	y		mv	il,sectsiz+1send_sect_3:	mv	a,[y++]		bsr	send_one			;Envoi de 129 octets de donnees CACHE		dec	il		jrnz	send_sect_3		mv	a,$ff		bsr	send_one			;Envoyer une marque de terminaison normale		bsr	receive_one		test	(flag),2		jrz	send_ok		mv	ba,-1		mv	[y],ba				;Invalider le cache mis en cachesend_ok:	popu	imr		ret;----------------------------------------------------------------------;		Reception 1 secteur;----------------------------------------------------------------------rcv_sect:	pushu	imr		pushu	il		pre	$30		mv	(intr_mask_reg),$a0		bsr	send_cache			;Traitement CACHE		popu	il		jrnc	read_cache		;Sautez quand vous pouvez lire de CACHE		pushu	il		pushu	x		mv	x,(cachep)			;Charger dans CACHE		mv	a,'R'		bsr	send_one			;Envoyer une commande de lecture		mv	a,(sect_num)		bsr	send_one			;Transmission inferieure a 1 octet du numero de secteur		mv	a,(sect_num+1)		bsr	send_one			;Envoi du 1 octet superieur du numero de secteur		rc		bsr	receive_one			;(Taille du secteur + 1) reception octet		jrc	rcv_sect_2		mv	[x++],a		mv	il,sectsizrcv_sect_1:	bsr	receive_one		mv	[x++],a		dec	il		jrnz	rcv_sect_1rcv_sect_2:	popu	x		popu	ilread_cache:	mv	[--s],u			;Lire de CACHE		mv	u,(cachep)		test	(flag),2		jrz	read_cache_1		mv	ba,-1		mv	[u+cache_sect],ba;Invalider le cache entrant		jr	rcv_errread_cache_1:	popu	ba		;mv	ba,[u++]		mv	[x++],ba		mv	[y++],ba		dec	il		jrnz	read_cache_1rcv_err:	mv	u,[s++]		popu	imr		ret;----------------------------------------------------------------------;		Transmission sur 1 octet;----------------------------------------------------------------------send_one:	pre	$30		test	(sio_stat_reg),$8		jrz	send_one			;Attendez qu'il soit pret pour Tx		test	(flag),2		jrz	send_one_2			;En mode d'arret de la transmission, 00h est transmis		mv	a,0send_one_2:	pre	$30		mv	(sio_tx_reg),a		;Envoyer		ret;----------------------------------------------------------------------;		Recevez 1 octet;----------------------------------------------------------------------receive_one:	jr	receive_one_s		db	system_stat_reg,8;		test	(system_stat_reg),8		jrnz	receive_one_err	;[BRK] a ete presse		test	(flag),1		jrz	receive_one			;Attendez qu'un octet soit recu		mv	a,(rxdata)		and	(flag),$fe			;Reinitialiser le drapeau		retreceive_one_s:	mv	ba,timeoutreceive_one_lp:	pre	$30			;1		test	(system_stat_reg),8	;4		jrnz	receive_one_err		;2		test	(flag),1		;4		jrnz	receive_one_ok		;2		dec	ba			;3		jrnz	receive_one_lp		;3		screceive_one_err:or	(flag),2	;Definir le mode d'arret de la transmission		retreceive_one_ok:	mv	ba,$6530	;pre $30 test (m),n		rel mv	[receive_one],ba		mv	a,(rxdata)		and	(flag),$fe			;Reinitialiser le drapeau		ret;----------------------------------------------------------------------;		Recevez une routine de traitement des interruptions;----------------------------------------------------------------------rcv:		pre	$30		mv	a,(sio_rx_reg)		mv	(rxdata),a		or	(flag),1			;Definir le drapeau de reception complete		retf;----------------------------------------------------------------------;		Tampon clair;----------------------------------------------------------------------buffer_clr:	mv	il,sectsiz+2		mv	ba,0		rel mv	x,sect_1buffer_clr_1:	mv	[x++],ba	;Remplir le tampon avec 00h		dec	i		jrnz	buffer_clr_1		mv	ba,-1		rel mv	[sect_number],ba	;Initialisation du numero de secteur		mv	il,n_fcache		rel mv	y,fcache		rel mv	[fcachep],y		bsr	buffer_clr_3		;Initialisation du cache FAT		mv	il,n_dcache		rel mv	y,dcache		rel mv	[dcachep],y		bsr	buffer_clr_3		;Initialisation du cache de donnees		retbuffer_clr_3:	mv	x,y		mv	[x+cache_sect],ba		dec	il		jrz	buffer_clr_2		mv	ba,cache_size		add	y,ba		mv	[x+cache_next],y		jr	buffer_clr_3buffer_clr_2:	mv	y,$fffff		mv	[x+cache_next],y		ret;----------------------------------------------------------------------;		Verification de la correspondance du tampon pour la commande $ 17;----------------------------------------------------------------------check_sect:	rel mv	x,sect_1		mv	il,sectsiz+1check_sect_3:	mv	(i_work1),[x++]		mv	a,[x+sectsiz+1]		cmp	(i_work1),a			;Comparaison du contenu de la memoire tampon		jrnz	check_sect_4		dec	il		jrnz	check_sect_3		retcheck_sect_4:		rel mvw	(sect_num),[sect_number]		rel mv	x,sect_1		mv	il,sectsiz+1		pushu	x		bsr	send_sect			;Pour expulser le tampon		popu	x		mv	ba,(sect_num)		inc	ba		mv	(sect_num),ba		dec	ba		dec	ba		mv	(sect_num2),ba		mv	y,(cachep)check_sect_6:	mv	ba,[y+cache_sect]		cmpw	(sect_num),ba		jrnz	check_sect_5		pushu	a		mv	a,[x+sectsiz]		mv	[y],a				;Le premier octet du secteur a cote du secteur accede		popu	acheck_sect_5:	cmpw	(sect_num2),ba		jrnz	check_sect_7		mv	a,[x]		mv	[y+sectsiz],a		;Le 129eme octet du secteur avant le secteur accedecheck_sect_7:	mv	y,[y+cache_next]		pushu	y		inc	y		popu	y		jrnz	check_sect_6		ret;----------------------------------------------------------------------;		Verification de la correspondance avec le cache;----------------------------------------------------------------------send_cache:		pushu	x		pushu	y		rel mv	x,dcachepsecpatch:	mv	ba,dtop			;Le numero du secteur principal de la zone DATA est ecrit		cmpw	(sect_num),ba		jrnc	send_cache_0		rel mv	x,fcachepsend_cache_0:	mv	(cachep),x		mv	(before),x		mv	x,[x]send_cache_1:	mv	ba,[x+cache_sect]		mv	y,[x+cache_next]		cmpw	(sect_num),ba		jrz	send_cache_2		;Le secteur auquel on a tente d'acceder est le meme que CACHE		pushu	y		inc	y		popu	y		sc						;Marquez qu'il ne peut pas etre lu de CACHE		jrz	send_cache_2		mv	a,cache_next		add	x,a		mv	(before),x		mv	x,y		jr	send_cache_1send_cache_2:	mv	[(before)],y		mv	y,[(cachep)]		mv	[x+cache_next],y		mvw	[x+cache_sect],(sect_num)		mv	[(cachep)],x		mv	(cachep),x		popu	y		popu	x		retprgend:;----------------------------------------------------------------------;		Zone de travail;----------------------------------------------------------------------suborg		*byte		sect_1[sectsiz+1+1],sect_2[sectsiz+1+1]pntr		fcachep,dcachepbyte		fcache[cache_size*n_fcache]byte		dcache[cache_size*n_dcache]word		sect_numberblen:		equ	%-btop		end